INSERT INTO video_impl_claims VALUES(76,'wau-YCos8IE','team_axis',NULL,'ATM',NULL,NULL,'formation','명목 4-4-2 ↔ 실질 하이브리드(백5/백4 전환), 축은 요렌테의 위치','「**lining up in a 4-4-2, but in the first 15 minutes they confused us**… it was like **a three at the back — very much a hybrid format, like five at the back sometimes, four at the back sometimes — but it was all around Llorente''s position**」(**4-4-2로 선다고 봤는데 첫 15분에 혼란스러웠다**… **백3 같았다 — 때로는 백5, 때로는 백4인 하이브리드 — 그런데 전부 요렌테의 위치를 중심으로 돌았다**)','PENDING','⚠️⚠️ **HANDOFF 미해결 1(ATM 포메이션 표기 충돌)의 세 번째 표기다** — 우리·El Desmarque·COPE는 4-4-2, Infobae는 4-3-3, `Y5xXltqB6uo`는 3-4-2-1↔백5, 이 자료는 **「명목 4-4-2 ↔ 실질 하이브리드」**. ⭐⭐ **그런데 이 자료가 충돌을 해소할 열쇠를 준다**: 표기가 갈리는 이유가 **요렌테 한 칸의 높이**이고, 그가 어디 있느냐에 따라 백3/백4/백5로 **보이는** 것이다. ⇒ 마감 조건: 요렌테의 경기별 `avg_x`·`pos_class`를 시계열로 뽑아 **그 한 칸의 이동으로 표기 충돌이 설명되는지** 검증. 설명되면 미해결 1을 「표기 문제가 아니라 유동 구조」로 닫을 수 있다. ⭐ 이것이 `i_nG7i-vavk`·`Vcps1dALdnE`의 「요렌테를 전진시켜라」 제안과도 같은 축이다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(77,'iHtB-noxtgg','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(78,'kURILCR5GQA','limit',NULL,NULL,NULL,NULL,'pressing','전방 6인 압박이 단절돼 돌아가기 쉬웠다 — 스트라이커가 닿는 속도와 중앙 미드 2인의 합류가 어긋난다','「**Isak probably not quite getting there quickly enough**… **Szoboszlai and Mac Allister were trying to latch on, pressing with the front six**, but **it was very disjointed, quite easy to play around**」(**이삭이 충분히 빨리 닿지 못했고**… **소보슬라이와 맥 알리스터가 전방 6인과 함께 압박하려 달라붙었지만 매우 단절돼 돌아가기 쉬웠다**)','HELD','✅ `reproduction_limits`에 「압박 강도·트리거 슬라이더가 없다」로 이미 등록된 한계다 — 새 행 추가 없음. ⭐⭐ **다만 이 자료는 「누가 어긋나는가」를 특정한 세 번째 소스**다: `67TNBKbdUDw`(트리거가 상대 형태에 종속) · `Y5xXltqB6uo`(압박 기준점이 깨끗하지 않음) · 이 영상(스트라이커 도달 속도 ↔ 중앙 미드 합류의 불일치). ⇒ 재판정 조건: FC26에서 이 불일치를 **역할 조합으로 간접 조절**할 수 있는지 — ST 포커스(Attack↔Support)와 DM/CM 포커스(Ball-Winning↔Defend)의 조합이 압박 합류 타이밍에 영향을 주는지 인게임 A/B 후보.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(80,'mtmL8cH18Qo','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(81,'c5etzTzcUQs','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(82,'BG7OGbbKmY0','role',50,NULL,'cm_dlp',NULL,NULL,NULL,'「**Mac Allister was really instrumental getting on the ball, dictating the play. He''s that real passer in the middle. Once he started to make things tick, Liverpool started to tick as a team**」(**볼을 잡고 경기를 지휘하는 데 결정적이었다. 중앙의 진짜 패서다. 그가 돌아가기 시작하자 팀도 돌아가기 시작했다**)','PENDING','⚠️ **우리 `#491`은 현재 role·focus·fit이 전부 NULL이다** — obs#770에서 **클럽 공식전에 2경기 이상 가진 pos_class가 하나도 없어**(RDM 1·LDM 1·CAM 1) 집계를 무효화했다. 이 자료는 그를 **딥라잉 플레이메이커 계열**로 보는 서사 근거를 주지만 **실측이 없어 처방을 만들 수 없다**(값을 발명하지 않는다). ⇒ 마감 조건: ⓐ `pos_class` 백필 후에도 그는 7월 대표팀 5경기가 **FIFA World Cup**이라 공식전 집계에 못 들어간다(obs#773) ⓑ **PL·UCL에서 같은 pos_class 2경기**가 쌓이면 즉시 재산출. 그때 이 서사와 실측 argmax를 대조한다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(83,'CQfQUokBtQo','limit',NULL,NULL,NULL,NULL,'in_possession','리버풀이 중원과 양 측면(특히 우측)에서 열려 있었다 — rest-defense 결손의 세 번째 독립 관측','「**Liverpool were really, really open, particularly in the middle of the park and down both flanks — particularly the right flank**」(**리버풀이 정말 열려 있었다 — 특히 중원과 양 측면, 그중에서도 우측**)','PENDING','⭐⭐ **같은 경기에서 rest-defense 결손을 지목한 세 번째 소스**다: `67TNBKbdUDw`(「rest defense isn''t fixed」) · `kURILCR5GQA`(「미드필드를 지나면 큰 열린 공간」) · 이 영상(「중원과 우측이 열려 있었다」). 여기에 `K6PKQW16wv0`(리즈)의 같은 진단까지 더하면 **4소스**다. ⇒ **`reproduction_limits`에 「rest-defense = 점유 중 볼 뒤 형태는 설정 축이 아니라 역할 조합의 창발 속성」을 `in_possession` 신규 행으로 등록할 근거가 충분해졌다**(K6PKQW16wv0의 같은 주장과 통합 처리). ⏰ 마감 조건: 등록 여부 사용자 판단 — 등록하면 「우리가 재현할 수 없는 것」 목록이 하나 늘고, 대신 **역할 조합(피벗 포커스·풀백 전진도)으로 간접 조절**한다는 지침이 붙는다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(84,'7Afj8XxiVW0','role',58,NULL,'wm_winger','Attack',NULL,NULL,'「**attitude is good. It''s positive, his attitude**… **training''s fine, but the matches — we need to lock in a little bit more**」(**태도가 좋다. 그의 태도는 긍정적이다**… **훈련은 괜찮은데 경기에서는 조금 더 집중해야 한다**)','HELD','⭐ 감독이 **훈련↔경기 격차**를 지목했다 — 즉 **아직 주전이 아닌 이유를 감독이 설명**한 것이다. 우리는 obs#768에서 **LM 주전을 헤밍스로 확정**했고(`wm_widemid/Support`, C1 뱅크 0.60), 가르나초는 `squad_entries` WM `wm_winger/Attack` .771로 **대안 후보**로만 보유 중이다 ⇒ 처방 변경 없음. ⚠️ **재판정 조건**: ⓐ 가르나초가 LM 선발로 포지션-순수 2경기 이상 뛰면 재산출 ⓑ 할 일 20(C2/C6 재판정)에서 **좌측 뱅크 부담이 다른 칸으로 옮겨지면** 그의 `winger/Attack`(뱅크 0.00)이 다시 후보가 된다. ⛔ 이 인용은 **진행자의 재진술**이라 verbatim 근거로는 약하다 — 원 회견 전사 확보 시 교체.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(85,'vePNdukB1DA','instruction',NULL,'CHE',NULL,NULL,'second_half_change','하프타임 4교체 + 「좁게 서서 중원 과부하」 지시 — 리스 제임스↔왓슨, 네투↔귀스토, 파머↔에스테방, 로저스↔기텐스','「Chelsea made **four changes: Reece James on for Reggie Watson, Pedro Neto on for Gusto, Palmer on for Estêvão, and Morgan Rogers on for Gittens**. And **very quickly you could see that Palmer and Rogers had been told to stay narrow and overload the midfield**」(첼시가 **4교체를 했다 — 리스 제임스↔레지 왓슨, 페드루 네투↔귀스토, 파머↔에스테방, 모건 로저스↔기텐스**. 그리고 **파머와 로저스가 좁게 서서 중원을 과부하시키라는 지시를 받았음이 아주 빠르게 보였다**)','HELD','⭐⭐ **할 일 28 ⓒ 해소** — 후반 변경의 정체가 확정됐다: **4교체 + 「좁게 서서 중원 과부하」 지시**다. `K6PKQW16wv0`(리즈 관점)이 「로저스·파머·리스 제임스가 첼시의 얼굴을 완전히 바꿨다」고 한 것의 **첼시 쪽 세부**이고, 교체 명단이 **두 소스에서 일치**한다. ⭐ 추가 지시도 특정됐다 — 네투·차바리아는 「**상대 공격이 올 때는 수비하고 공간이 생기면 공격하라**」, **리스 제임스와 바르코는 백라인에 내려가고 다른 한 명이 올라간다**(로테이션). ⛔ 그러나 `reproduction_limits` `situational` 축이 「단일 정적 프리셋은 전·후반 차이를 담지 못한다」로 이미 막아 둔 영역이라 **FC26에 옮길 설정이 없다** ⇒ 변경 없음. ⭐ **재판정 조건: `match_game_setups`를 전·후반으로 분리할지** — 이 경기는 전·후반이 다른 팀이었다는 증언이 **2소스**이고 교체·지시까지 특정됐으므로 **분리 설계의 첫 시험대**로 쓸 수 있다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(86,'vePNdukB1DA','team_axis',NULL,'CHE',NULL,NULL,'formation','4-3-3 (SofaScore 정본) · 영상의 「빌드업 백3 ↔ 무공 4-4-2」는 국면 서술','「**three at the back in build-up** — Lacroix in the centre, Colwill, Acheampong」(**빌드업에서 백3** — 중앙 라크루아·콜윌·아체암퐁) / 「out of possession, **it shifted more to a 4-4-2**」(무공 시 **4-4-2로 이동**)','REJECTED','⛔ **명목 포메이션 주장으로는 기각한다** — obs#777에서 SofaScore 원천(`event/16950621/lineups`)을 브라우저 경로로 조회한 결과 **첼시는 `4-3-3`**이었다(리즈가 3-4-2-1). ⭐ **모순은 아니다**: 영상은 **국면별 형태**(빌드업 백3 / 무공 4-4-2)를 서술했고 SofaScore는 **명목 포진**을 기록한다 — **층이 다르다.** ⇒ ⭐⭐ **부류로 기록**: 「팬 채널의 포메이션 서술은 국면 서술일 수 있다」. 우리가 영상 값을 직접 채우지 않고 **수집 후 대조용으로만 쓴 판단이 옳았다**(3티어 소스 보류 원칙). ⭐ 국면 형태 자체는 `reproduction_limits` `formation` 축(「FC26은 국면별 포메이션을 갖지 않는다」)에 이미 등록된 한계에 해당한다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(87,'N-oZ3Cn_XDc','role',50,NULL,'dm_dlp','Roaming',NULL,NULL,'「**Gravenberch is not my number six… So going forward, Alexis Mac Allister is my number six**」(**흐라벤베르흐가 내 6번이 아니다… 앞으로 맥 알리스터가 내 6번이다**) · 「Every time Mac Allister played, **we looked like a team that could move the ball forward when we need to and then defend when we needed to**」(그가 뛸 때마다 **필요할 때 전진시키고 필요할 때 수비하는 팀으로 보였다**)','PENDING','⚠️⚠️ **우리 `#491` 맥 알리스터는 role·focus·fit이 전부 NULL이다** — obs#770에서 **클럽 공식전에 2경기 이상 가진 `pos_class`가 하나도 없어**(RDM 1·LDM 1·CAM 1) 집계를 무효화했다. 그런데 **이 영상과 `BG7OGbbKmY0`(「그가 돌아가자 팀이 돌아갔다」, 48터치)가 그를 딥라잉 6번으로 지목**한다 ⇒ **서사 2소스가 실측 공백을 가리키고 있다.** ⛔ 값을 발명하지 않는다 — 처방 없음 유지. **마감 조건: PL·UCL에서 같은 `pos_class` 2경기**가 쌓이면 즉시 재산출하고 이 서사와 argmax를 대조한다(7월 대표팀 5경기는 `FIFA World Cup`이라 공식전 집계에서 제외됨, obs#773).','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(88,'N-oZ3Cn_XDc','role',49,NULL,'dm_dlp',NULL,NULL,NULL,'「**he''s not naturally a six**… **He doesn''t have the awareness to play as a six**… we looked a lot more exposed」(**그는 천성적 6번이 아니다**… **6번으로 뛸 인지 능력이 없다**… 우리는 훨씬 더 노출됐다)','REJECTED','⛔ **실측이 반대 방향이다**(docs/30 7단계 ⑷ 반박권 행사) — 우리 `#368` 흐라벤베르흐는 **LDM 순수 2경기(119분)** 재집계에서 `dm_dlp/Roaming` **.7633**(2위 `dm_dlp/Build-Up` .6485, **Δ.1148 > .05 단독 확정**)이다. 즉 **커널은 그를 그 자리에 잘 맞는다고 본다.** ⚠️ 다만 두 가지 유보: ⑴ **표본이 2경기로 규약 하한**이다(obs#772에서 「얇은 표본 3건」으로 표시) ⑵ **영상의 주장은 「적합」이 아니라 「수비 인지」**라 층이 다르다 — 커널은 **위치 분포**를 보고 영상은 **판단 능력**을 본다(docs/22 PlayStyle·능력치 층). ⇒ 역할 변경 없음. **재판정 조건: LDM 순수 표본이 4경기 이상으로 늘었을 때 재산출** + 실점 국면의 6번 공간 노출을 실측으로 확인.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-15','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-15');
INSERT INTO video_impl_claims VALUES(89,'zFvDU2SSXMo','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA','이 영상의 전술 주장은 (ㄱ) 다음 경기 예상 라인업이거나 (ㄴ) 요렌테 중원 선발 확인이다. 전자는 D+3 회차 범위 밖(예상은 근거 불가), 후자는 obs#803이 AS 1차 + WhoScored 포진 좌표로 이미 확정했다. 역할·포커스 수준의 새 구현 주장 없음.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-16','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-16');
INSERT INTO video_impl_claims VALUES(90,'C8zTc8rvTr4','role',167,NULL,'fb_att_wb','Attack',NULL,NULL,'「a Grimaldo todo el carril no le puedes dar, le tienes que poner a alguien fijando la amplitud por izquierda… Grimaldo ayer crece cuando Arnau Ortiz abre bien la banda, ya se puede meter por dentro」(그리말도에게 카릴레로 전체를 줄 수는 없다. 좌측에서 폭을 고정해 주는 누군가를 붙여야 한다… 어제 아르나우가 측면을 잘 열어 주자 그리말도가 성장했고, 이제 안쪽으로 들어갈 수 있다) — auto-caption','HELD','⛔ 이 회차에 처방을 바꾸지 않는다. 주장은 「전진 자체」가 아니라 「전진의 조건(같은 쪽 폭 제공자)」이라 단일 역할 코드로 환원되지 않고, 좌측 와이드 슬롯의 역할(폭 제공형 winger)과 한 쌍으로만 성립한다. 재판정 조건: ⑴ 아르나우(또는 다른 폭 제공형 와이드) 선발 + 그리말도 좌측 카릴레로 조합이 공식전 2경기 확보 ⑵ 그 표본에서 그리말도 그리드가 안쪽(열 이동)으로 실제 이동하는가. 근거 무효화 조건: 폭 제공자 없이도 그리말도 전진이 재현되면 이 주장은 무효다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-16','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-16');
INSERT INTO video_impl_claims VALUES(91,'C8zTc8rvTr4','role',158,NULL,'w_insidefwd','Attack',NULL,NULL,'「si me llega el balón aquí a la banda izquierda, voy a hacer mi recorte hacia dentro, mi amaguito y gol」(볼이 좌측에 오면 안쪽으로 커트해 들어가 페인트하고 골) / ⛔ 반대편: 「en ese 433 por la izquierda a Lukman no le veo… no está funcionando」(그 4-3-3에서 좌측의 루크먼은 안 보인다… 작동하지 않는다) — auto-caption','HELD','같은 영상이 유형(안쪽 커터 = insidefwd 계열)과 가동 여부(좌측에서도 작동하지 않는다)를 동시에 말해 역할 축과 폼 축이 분리되지 않는다(obs#807). 실측은 이 경기 ST 배치의 st_advanced/Support .603뿐이고 좌측 슬롯 표본이 없다. 재판정 조건: 루크먼이 좌측 슬롯(LM/LW)에서 공식전 45분+ 2경기를 채우면 커널 재산출 후 판정. 그때까지 시즌 정본 미변경.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-16','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-16');
INSERT INTO video_impl_claims VALUES(92,'zXWZ2eeDynQ','team_axis',NULL,'ATM',NULL,NULL,'rest_defense_left','LCB covers LWB back','「특히 아틀레티코의 좌측 그림말도가 공격적으로 올라간 뒤의 공간을 계속 노렸습니다… 한츠코가 그 뒤를 계속 커버해야 했습니다」 (원 한국어 — 번역 불요) / 대조 1차: AS 「En Anoeta, el sistema de tres centrales… protegió a Grimaldo en ese carril izquierdo」(아노에타에서 백3 체계가… 좌측 카릴레로에서 그리말도를 보호했다) — auto-caption','APPLIED','obs#808로 채택. 백3의 기능을 「양쪽 카릴레로 등 뒤 보증」으로 규정하는 근거이며, 상대 매체·스페인 전국지·한국어 채널 3진영이 좌우 양쪽에서 같은 구조를 서술한다. ⛔ 팀 설정 필드(빌드업·수비접근·라인) 변경은 아니다 — 구조 해석의 채택이고 match_game_setups는 그대로다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-16','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-16');
