INSERT INTO video_impl_claims VALUES(105,'JPauDiMsUw0','instruction',86,NULL,NULL,NULL,'added_asset','speed_direct_running','「adding individual skills like today and [Mbaye] his speed」(오늘처럼 개인 기량을 더하는 것 — 그의 스피드)','NA','게임 구현 축이 아니다 — 「오늘처럼 개인 기량과 스피드를 더한다」는 선수 평가·기대 표현이지 역할·포커스·팀 설정 어느 것도 지정하지 않는다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-17');
INSERT INTO video_impl_claims VALUES(106,'ZWveSji6X6s','limit',NULL,'AVL',NULL,NULL,'double_pivot','barkley_bogarde_pairing_unstable_on_ball','「when Barkley and Bogard were on the ball, my gut was going ''no, what are they going to do? Something bad''s going to happen''」(바클리와 보가르드가 볼을 잡으면 직감적으로 나쁜 일이 생기겠다 싶었다)','HELD','실측 평점 바클리 7.8·보가르드 7.4(SofaScore) ↔ 서사 5점 — 충돌(D+1 미해결 목록과 같은 건). 재판정 조건: 고메스 복귀 후 「고메스-보가르드」 vs 「바클리-보가르드」 피벗 짝 표본 각 2경기의 자기진영 상실 비교.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-17');
INSERT INTO video_impl_claims VALUES(107,'ZWveSji6X6s','instruction',132,NULL,NULL,NULL,'gk_long_distribution_target','mbaye_run_in_behind','「I like the idea of him pinging it to [Mbaye]… with him running in behind」(스즈키가 음바예에게 꽂아주고 그가 배후로 침투하는 그림)','HELD','검증 불가 — 「GK가 음바예에게 꽂고 배후 침투」는 **패스 방향·길이 데이터**가 있어야 판정된다. 우리는 스즈키의 패스맵을 갖고 있지 않다(SofaScore 요약 스탯만). 재판정 조건: WhoScored 이벤트에서 GK 롱패스 수신자와 음바예 오프사이드 라인 침투를 집계하면 닫는다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-17');
INSERT INTO video_impl_claims VALUES(108,'Lr4ktnv-FeE','instruction',90,NULL,NULL,NULL,'rb_build_up_shape','tuck_in_hybrid_back3','「Wasaka more staying at home in a hybrid back three」(완비사카는 하이브리드 백3에서 집을 지켰다)','REJECTED','실측 불일치: 완비사카 avg_y 14.69 → 툴x 85.3(터치라인). 백3로 접혔다면 툴x가 CB 대역(58~70)으로 들어와야 한다. 전진 억제(avg_x 41 < LB 47)는 정합하므로 「억제형 풀백(fb_wingback/Balanced)」 처방은 그대로. 1874(EmS_1gJ6g9c)도 같은 주장 — 2소스지만 둘 다 평균위치 그래픽의 y축 해석 오류로 판단.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-17');
INSERT INTO video_impl_claims VALUES(109,'Lr4ktnv-FeE','limit',NULL,'AVL',NULL,NULL,'set_pieces','near_post_target_repeated','「Them set pieces are starting to look good at the near post… We''ve done him twice」(세트피스가 니어포스트에서 좋아지고 있다… 두 번 해냈다)','HELD','D+1 판별 (b)는 「설계 루틴 아님 — 배급 품질+상대 마킹 실패」였다. 니어포스트 반복(2골 모두)은 새 관측. 재판정 조건: §7 재검증 ⑷ — 다음 경기 코너 니어포스트 타깃 3번째 표본이면 「루틴」으로 승격.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-17');
INSERT INTO video_impl_claims VALUES(110,'EmS_1gJ6g9c','instruction',86,NULL,NULL,NULL,'winger_width','hold_touchline_right','「he obviously wanted Embay to hold that width on the right hand side」(그에게 우측 폭을 유지시키려 한 게 명확히 보였다)','HELD','⚠️ 부분 성립 — 음바예 점유 좌우 73.1은 **半-와이드**다. 같은 경기 완비사카가 84.7로 더 바깥이었고 음바예 전진도는 68.7로 높다. 「폭 유지」 지시가 있었다 해도 그 결과는 터치라인 고정이 아니라 안쪽 침투를 겸한 형태다. 재판정 조건: 우측 배치 경기에서 점유 좌우값 80 이상이면 APPLIED.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-17');
INSERT INTO video_impl_claims VALUES(111,'EmS_1gJ6g9c','instruction',90,NULL,NULL,NULL,'rb_build_up_shape','tuck_in_hybrid_back3','「Aaron Wasaka kind of tucked in and made a back three alongside Mings and Harwood Bellis」(완비사카가 안으로 접혀 백3를 만들었다)','REJECTED','UTV(Lr4ktnv-FeE)와 같은 주장 · 같은 사유로 기각 — 실측 툴x 85.3(터치라인). 2소스 일치가 실측을 이기지 않는다(불변규칙 3).','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-17');
INSERT INTO video_impl_claims VALUES(112,'qS27lBoSUqw','role',21,NULL,'cm_playmaker','Attack',NULL,NULL,'「push forward a bit or go in the 10 role… quickly recycle it, pick out a good pass and hit one from distance」(조금 전진하거나 10번 롤로… 빠른 재순환·좋은 패스·중거리)','HELD','실측 LDM avg_x 49.77 = 피벗 중 최전방(보가르드 40.1)·평점 7.8 — 이미 전진형으로 뛰었다. 현 경기 처방은 LDM 축이라 CM 어휘 대조는 measured 재산출(피벗 표본 2경기) 후. 재판정 조건: 바클리 LDM 공식전 2경기째 pos_class 집계 → 커널 1·2위 Δ 확인.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-17');
INSERT INTO video_impl_claims VALUES(113,'qS27lBoSUqw','role',178,NULL,'cb_bpd','Build-Up',NULL,NULL,'「Harwood-Bellis is putting it [into the same area] but tends to lift it a bit more」(하우드-벨리스도 같은 지역에 넣는데 조금 더 띄운다)','APPLIED','실측 지지 — 하우드-벨리스 패스 71회·정확도 65%로 시도량은 많고 정확도는 낮다(띄우는 배급의 흔적). 점유 국면 위치 전진 32.2·좌우 61.2로 좌측 하프스페이스에서 전개했다. 슬롯 정본(LCB cb_bpd/Build-Up)과 정합 — 파우 토레스 결장 구간의 대체안 근거로도 쓴다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-17');
INSERT INTO video_impl_claims VALUES(114,'qS27lBoSUqw','limit',86,NULL,NULL,NULL,'selection_gate','away_defensive_workload','「is he defensively going to do the job for us yet… do I maybe go with Allison on the right who will do the defensive duties」(아직 수비 임무를 해낼 수 있는가… 수비 임무를 해줄 알리송을 오른쪽에)','APPLIED','실측 지지 — 음바예 64분에 태클 0·인터셉트 0, 비점유 국면 전진도 63.3으로 **수비 라인으로 내려오지 않았다**. 「아직 수비 임무를 못 맡긴다」는 한계 주장이 국면 그리드로 확인된다. ⇒ 게임 구현: 우측을 해방형으로 쓰면 그 뒤를 풀백(완비사카 비점유 28.8)이 혼자 감당한다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-17');
INSERT INTO video_impl_claims VALUES(115,'M54FnnHg-Ac','limit',NULL,'AVL',NULL,NULL,'set_piece_defence','free_kick_wall_too_deep','「As soon as I saw the wall go back as far as it did, I [knew] he could score here」(벽이 그만큼 물러나는 걸 본 순간 여기서 넣겠다 싶었다)','HELD','⚠️ 단일 소스(상대 팬 채널) — 27′ 실점의 「벽이 물러났다」 주장은 D+3까지도 2차 소스가 붙지 않았다. 반대로 GK 도달 실패는 **두 소스**가 일치한다(Tanswell 「제자리에 굳어 있었다」 · Aston Villa Review 「프리킥에 가까이 가지도 못했다」). 재판정 조건: 하이라이트 프레임에서 킥 시점 벽 위치를 확인하면 닫는다. 그 전까지 세트피스 수비 처방을 이 주장으로 바꾸지 않는다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-17');
