INSERT INTO video_impl_claims VALUES(125,'gaZwLEsP4wY','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA','전술 구조 설명은 풍부하나 FC 역할·포커스·팀 설정 어휘로 옮길 수 있는 명시 주장이 없다. 쿠마스 평가는 obs#819의 기존 판정을 재확인할 뿐 새 값 주장이 아니다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-18');
INSERT INTO video_impl_claims VALUES(126,'4Zly8FIdpr4','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA','상대 관점 서술이며 리버풀 측 FC 역할·포커스·팀 설정에 대한 명시 주장이 없다. 압박 인원 6명 서술은 obs#818 재확인이지 새 설정값 주장이 아니다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-18');
INSERT INTO video_impl_claims VALUES(127,'mZYZ5LVPtDA','instruction',86,NULL,NULL,NULL,'width','우측 터치라인 폭 유지(기본 위치)','「he stretches the opposition defense immediately just with his starting point as he forces the fullback to break away from a narrow defensive shape」(시작 위치만으로 상대 수비를 즉시 벌리고, 풀백이 좁은 수비 형태에서 떨어져 나오게 만든다)','APPLIED','D+1 PENDING(1874 단독)에서 승격 — 독립 4소스(1874·Talk Villa·Tanswell 현장·프랑스어 매체)가 「우측 폭」으로 일치하고, 실측 툴x 72.4(맥긴 67.8보다 바깥, 터치라인 85는 아님)는 Tanswell이 관찰한 맥긴·완비사카와의 설계된 자리바꿈으로 설명된다 — 즉 기본은 폭, 평균이 안쪽인 것은 로테이션의 결과다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','MEDIUM-HIGH — auto-caption. 단일 경기·하부 리그 상대.','2026-09-18');
INSERT INTO video_impl_claims VALUES(128,'mZYZ5LVPtDA','instruction',86,NULL,NULL,NULL,'in_behind_runs','우측 채널 배후 침투(지시)','「There''s the space. That''s where it''s going to open up. I want you to attack it and make those runs in behind to give us a threat down the right channel」(저기가 공간이다. 저기가 열릴 곳이다. 저길 공략해 배후로 뛰어서 우측 채널에 위협을 만들어라)','HELD','화자가 에메리의 말을 재구성한 것이지 전사된 지시가 아니다(정지화면 해설). 방향은 Tanswell의 「배후를 상시 위협하는 우측 윙어가 이번 여름 최우선 과제였다」와 정합. 재판정 조건: 스퍼스 원정 이후 음바예의 배후 스루패스 수신 이벤트.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','MEDIUM — auto-caption · 인용은 화자의 재구성.','2026-09-18');
INSERT INTO video_impl_claims VALUES(129,'mZYZ5LVPtDA','limit',86,NULL,NULL,NULL,'defensive_work','원정 수비 임무 수행 — 첫 긍정 관찰','「I thought he put in some seriously hard yards to track his man and do the defensive part of his work as well… is that part of the process of he''s new here, he wants to impress」(자기 매치업을 따라가며 상당히 힘든 거리를 뛰었고 수비 몫도 해냈다 — 다만 새로 왔고 인상을 남기려는 과정의 일부인가)','HELD','⚠️ 반쪽만 맞다 — 「수비 몫도 해냈다」는 카운팅 스탯(태클 0·인터셉트 0)과 비점유 높이 63.3이 반대 방향이다. 다만 **대인 추적 주행**은 우리 데이터에 없다(이벤트 기반이라 오프더볼 거리를 못 센다). 재판정 조건: 다음 우측 배치 경기에서 비점유 전진도가 55 이하로 내려오거나 태클·인터셉트가 발생하면 APPLIED로 올린다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','LOW-MEDIUM — auto-caption · 단일 소스 · 하부 리그 상대.','2026-09-18');
INSERT INTO video_impl_claims VALUES(130,'p7YDUThRRXQ','role',10,NULL,'cam_halfwinger',NULL,NULL,NULL,'「he has the freedom to go out onto that right side from the central areas and Mbaye particularly has that intelligence to cut inside and dovetail with him」(중앙에서 우측으로 나갈 자유가 있고, 음바예는 안쪽으로 접어 그와 맞물린다)','APPLIED','커널이 cam_halfwinger/Roaming .502를 내면서 Δ0.012 무결정이었던 구간 중 **역할 축**을 서사가 닫는다 — 「중앙 배치 + 우측으로 드리프트」는 halfwinger의 정의 그대로이고, Tanswell 현장 관찰(「McGinn drifting over to the inside channel and overloading the right side with Mbaye, sometimes swapping positions」 맥긴이 안쪽 채널로 흘러 음바예와 우측을 과부하시켰고 때로 자리를 맞바꿨다)이 독립 2소스를 만든다. ⚠️ **포커스 축(Roaming↔Attack)은 여전히 무결정**으로 남긴다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','MEDIUM-HIGH — 독립 2소스(팬채널 auto-caption + 현장 기자 실시간 기록)가 커널 역할값과 일치.','2026-09-18');
INSERT INTO video_impl_claims VALUES(131,'p7YDUThRRXQ','role',178,NULL,'cb_bpd',NULL,NULL,NULL,'「he''s from that old school of centre halves… but what he''s also got is that ability to put his foot on the ball and pass into midfield」(구식 센터백 계보이지만, 발로 잡고 미드필드로 찔러주는 능력까지 있다)','HELD','슬롯 정본 cb_bpd/Build-Up과 방향 정합이고 D+1의 「파우 토레스와 같은 지역, 조금 더 띄운다」와도 겹친다. 그러나 **빌라 공식전 1경기·하부 리그 상대**라 승격하지 않는다. 재판정 조건: 스퍼스 원정 이후 프리미어리그 2경기 표본.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','MEDIUM — auto-caption · 표본 1경기.','2026-09-18');
INSERT INTO video_impl_claims VALUES(132,'p7YDUThRRXQ','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-18');
INSERT INTO video_impl_claims VALUES(133,'WajH4NOz_D0','limit',11,NULL,NULL,NULL,'progression','피벗 진취성 결여(수동성)','「I watched it back again today and… he''s even worse again on the second viewing… He was incredibly passive」(오늘 다시 돌려봤는데 두 번째 시청에서 더 나빴다… 극도로 수동적이었다)','HELD','D+1 미해결 충돌 1번을 닫지는 않되 **성격을 특정**한다 — 실측은 duels_won 11·tackles 3·패스 47/51(92%)로 **행동량**이 높고, 서사가 때리는 것은 **전진·주도**의 부재다(avg_x 40.1로 피벗 최전방 바클리 49.77보다 −9.7, 진영 최후방 피벗). 두 층이 서로 다른 것을 재고 있으므로 SofaScore 7.4와 서사 평점 4~5는 모순이 아니다. 재판정 조건: 고메스 복귀 후 같은 슬롯의 전진패스·프로그레시브 캐리 대조.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','MEDIUM — auto-caption · 재시청 기반 단일 화자. 실측과의 층 분리는 우리 판정.','2026-09-18');
INSERT INTO video_impl_claims VALUES(134,'WajH4NOz_D0','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-18');
INSERT INTO video_impl_claims VALUES(135,'fKDbTccRjGk','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-18');
INSERT INTO video_impl_claims VALUES(136,'At5v2hKj1vI','none',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'NA',NULL,'전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-18','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-18');
INSERT INTO video_impl_claims VALUES(137,'Jp52xd-xLt8','instruction',NULL,'AVL',NULL,NULL,'away_vs_top_game_plan','defend_deep_then_transition','원문 「we knew before the match, we needed defense and we needed to be so so resilient defensively. We needed the keeper saving us.」(경기 전부터 우리는 알고 있었다 — 수비가 필요하고 수비적으로 대단히 견뎌야 한다는 것을. 골키퍼가 우리를 구해줘야 했다.) — auto-caption','APPLIED','실측이 전면 지지한다: def_x 30.6(26/27 최저, optimal:vs-strong 라인 43보다 낮다) · PPDA 13.24 · 상대 진영 패스 102회 · 3골 전부 오픈플레이(세트피스 xG 0.00) · fast-break 슈팅 3회. match_game_setups(report 47)에 Counter/Balanced/라인 48로 이미 기록했다. 시즌 정본은 바꾸지 않는다(단일 경기).','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-20','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-19');
INSERT INTO video_impl_claims VALUES(138,'k6dbBj7Tz7w','instruction',NULL,'AVL',NULL,NULL,'defensive_shape_second_half','back_five_right_side_shift','원문 「sometimes with back four is not enough to defend completely the … side of the field … the second half we needed more with John McGinn」(때로는 백4로는 측면을 완전히 수비하기에 충분하지 않다 … 후반에는 존 맥긴으로 더 필요했다.) — auto-caption','APPLIED','실측이 독립 확인한다 — 맥긴 수비액션 x 전반 56.3 → 후반 32.1, y 32.8 → 18.2. 후반 57′·58′·77′ 수비액션이 x 11.8~16.2로 백4 라인 깊이이고 전반에는 그 대역이 0건이다. 단 좌측은 부엔디아가 반대로 35.6 → 47.6으로 올라가 대칭 5-3-2가 아니라 **우측 편중 백5**다. 리포트 §2·§6에 이 형태로 기록하고 manager_profiles.formation의 「5-3-2 전환 미관측」 서술을 정정 대상으로 올린다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-20','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-19');
INSERT INTO video_impl_claims VALUES(139,'k6dbBj7Tz7w','instruction',NULL,'AVL',NULL,NULL,'buildup_back_three_source','pivot_drop_kamara','원문 「someday we are the first half we use it more [Kamara] dropping dropping」(어떤 날은 전반처럼 카마라를 더 내려서 쓴다.) — auto-caption, Kamara가 「camera」로 오인식','HELD','**재판정 조건**: 이번 수집은 WhoScored 보유 이벤트를 분(分) 없이 받아 전반만 분리할 수 없었다. 다음 회차에 보유 이벤트를 expandedMinute 포함으로 재수집해 **전반 카마라 보유 x와 CB 라인 x(린델뢰프·밍스)를 대조**한다. 두 값의 격차가 8 이하로 좁혀지면 APPLIED, 아니면 REJECTED. 현재 경기 전체 평균(카마라 40.3 vs CB 25.7·26.1)만으로는 판정할 수 없다. manager_profiles.buildup의 기존 백3 경로(3-2-5·콘사 RB 변환)와 다른 새 경로 후보다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-20','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-19');
INSERT INTO video_impl_claims VALUES(140,'kJZ0G7WvLWY','team_axis',NULL,'AVL',NULL,NULL,'build_up_style','Counter','원문 「this season Aston Villa are playing 86% more long balls than last season, and we spoke in many many meetings yesterday and two days ago」(올 시즌 아스톤 빌라는 지난 시즌보다 롱볼을 86% 더 많이 하고 있어서, 어제와 이틀 전 수많은 미팅에서 그 얘기를 했다.) — auto-caption','APPLIED','상대 감독의 **정량 사전 스카우팅**이 우리 buildup 축 갱신(25/26 Short Passing → 26/27 상대 의존 고다이렉트)을 독립 확인했다. 이 경기 실측 롱볼 14.5%는 26/27 최고이고 core.team_settings.suggest도 Counter를 제안해 match_game_setups(report 47)에 Counter로 기록했다. ⛔ 시즌 정본 team_tactic_setups(Short Passing)는 바꾸지 않는다 — 에메리의 빌드업은 상대 의존이고 헐전 롱볼 5.6%가 같은 시즌에 있다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-20','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-19');
INSERT INTO video_impl_claims VALUES(141,'kJZ0G7WvLWY','instruction',NULL,'AVL',NULL,NULL,'gk_long_kick_route','goal_kick_to_ten_flick_to_nine','원문 「we conceded one unacceptable goal from long goal kick with a long ball」(우리는 롱 골킥에서 롱볼로 용납할 수 없는 골을 하나 내줬다.) — auto-caption','APPLIED','67′ 잭슨 골(xG 0.060)의 경로를 상대 감독이 직접 특정했다. 스즈키 패스 38회 중 성공 22(58%)·롱킥 비중이 이 루트의 실측 근거이고, 브뤼헤전에서 정식화한 「맨투맨 하이프레스 → 의도적 GK 백패스 → 스즈키 롱킥」의 3번째 표본이자 **첫 득점 전환**이다. 상대가 사전에 대비했는데도 성립했다는 점이 추가 정보다.','전사 원문 읽기 · scripts/write_video_summary.py, 2026-09-20','auto-caption 전사 기반 — 인물명·수치는 실측 교차검증 필요','2026-09-19');
